// Corona Glow and Stars - color only, ANIMATED. Runs INSIDE shadeSurface().
// A night sky painted on the object by DIRECTION: each point takes the color of
// the sky in the direction it lies from the center of the scene, so any object
// becomes a window on the same sky. In it: a star with a flaring corona that
// sways slowly around the direction SUN (by default the side the starting camera
// of the library surfaces looks at), a swirling nebula and three layers of
// twinkling stars.
// This version hides the disk of the star: only its light is drawn.
// No displacement: one evaluation per pixel, cheap at any resolution.
// In scope: pModel, t. Dock colors: u_col1 = light of the star, u_col2 = nebula.

float STARS  = 1.0 * max(E, 0.05);   // slider E   // star density           [0.3 .. 3]
float CORONA = 0.22 * max(F, 0.05);  // slider F   // corona size (radians)  [0.05 .. 0.6]
float DISK   = 0.0;                  // 1 = draw the disk of the star, 0 = only its light
float RADIUS = 0.16;                 // disk radius (radians)                  [0.05 .. 0.4]
float SWAY   = 0.15;                 // how fast the star sways (rad/s)        [0 .. 1]
vec3  SUN    = normalize(vec3(-0.5, 0.43, 0.75));   // where the star sits

vec3 dir = normalize(pModel + vec3(1e-5));

// --- the star: direction, angular distance, angle around it (for the flares)
vec3 sunDir = normalize(SUN + 0.25 * vec3(sin(SWAY * t), 0.5 * sin(0.7 * SWAY * t), 0.0));
float ang = acos(clamp(dot(dir, sunDir), -1.0, 1.0));
vec3 tu = normalize(cross(sunDir, vec3(0.0, 1.0, 0.0)));
vec3 tv = cross(sunDir, tu);
float phi = atan(dot(dir, tv), dot(dir, tu));
float flare = 0.55 + 0.25 * sin(7.0 * phi + 0.7 * t) + 0.2 * sin(13.0 * phi - 0.45 * t + 1.3);
float corona = exp(-max(ang - RADIUS * DISK, 0.0) / (CORONA * flare));

// --- nebula: a self-warping flow of sines in 3D
vec3 q = dir * 2.5;
for (int i = 0; i < 4; i++) {
    q += 0.55 * sin(q.zxy * 1.35 + vec3(0.11, 0.07, 0.05) * t + float(i));
}
float neb = 0.5 + 0.5 * sin(q.x * 0.9 + q.y * 1.1 - q.z * 0.7);
neb = neb * neb;

// --- stars: three layers of cells on the direction, at most one star per cell
float stars = 0.0;
vec3 starTint = vec3(0.0);
for (int L = 0; L < 3; L++) {
    float dens = (18.0 + 22.0 * float(L)) * STARS;
    vec3 sp = dir * dens;
    vec3 ci = floor(sp);
    vec3 h3 = fract(ci * vec3(0.1031, 0.1030, 0.0973) + 0.13 * float(L));
    h3 += dot(h3, h3.yxz + 33.33);
    vec3 hr = fract((h3.xxy + h3.yxx) * h3.zyx);
    vec3 rel = fract(sp) - (0.25 + 0.5 * hr);          // star inside its cell
    float size = 0.07 + 0.08 * hr.z * hr.z;
    float tw = 0.6 + 0.4 * sin(t * (1.5 + 3.0 * hr.x) + 6.2832 * hr.y);
    float st = 1.6 * exp(-dot(rel, rel) / (size * size)) * tw * step(0.45, hr.x);
    stars += st;
    starTint += st * mix(vec3(0.7, 0.8, 1.0), vec3(1.0, 0.85, 0.6), hr.y);
}

// --- composition
vec3 col = ubuf.u_col2 * (0.18 + 0.9 * neb);
col += starTint;
col += ubuf.u_col1 * corona * 1.2;
if (DISK > 0.5 && ang < RADIUS) {
    // disk with limb darkening and a boiling granulation
    float mu = sqrt(max(1.0 - (ang / RADIUS) * (ang / RADIUS), 0.0));
    float gran = 0.5 + 0.5 * sin(40.0 * dir.x + 3.0 * t) * sin(40.0 * dir.y - 2.0 * t) * sin(40.0 * dir.z + t);
    vec3 disk = mix(ubuf.u_col1 * 0.9, vec3(1.0, 0.97, 0.9), mu) * (0.9 + 0.1 * gran);
    col = mix(col, disk, smoothstep(RADIUS, RADIUS * 0.96, ang));
}

textureCol = col;
